{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n.get('parent')
        if pid is not None and pid in children:
            children[pid].append(n['id'])

    def get_descendants(nid):
        res = {nid}
        stack = [nid]
        while stack:
            cur = stack.pop()
            for child in children.get(cur, []):
                if child not in res:
                    res.add(child)
                    stack.append(child)
        return res

    sym_to_nodes = {}
    for n in nodes:
        sym = n['symbol']
        sym_to_nodes.setdefault(sym, []).append(n['id'])

    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed_set = set()
    removed_order = []

    for n in sorted_nodes:
        nid = n['id']
        if not n['removable'] or nid in removed_set:
            continue
        subtree = get_descendants(nid)
        can_remove = True
        for sid in subtree:
            if sid in removed_set:
                continue
            if not node_map[sid]['removable']:
                can_remove = False
                break
        if not can_remove:
            continue
        all_syms_ok = True
        for sym in required_symbols:
            found = False
            for sid in sym_to_nodes.get(sym, []):
                if sid not in removed_set and sid not in subtree:
                    found = True
                    break
            if not found:
                all_syms_ok = False
                break
        if not all_syms_ok:
            continue
        removed_order.append(nid)
        removed_set.update(subtree)

    retained_ids = [n['id'] for n in nodes if n['id'] not in removed_set]
    retained_ids.sort()
    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_ids
    }"
}
